// 16 Block Well
const FORMAS = { busca: [[0, 1], [1, 0], [1, 1], [1, 2], [2, 1]], ler: [[0, 0], [1, 0], [1, 1]], editar: [[0, 0], [0, 2], [1, 0], [1, 1], [1, 2]], terminal: [[0, 0], [0, 1], [0, 2], [0, 3], [0, 4]], agente: [[0, 0], [0, 1], [0, 2], [1, 1], [2, 1]], web: [[0, 0], [0, 1], [1, 0], [1, 1], [2, 0]] };
const FORMA_DE = { Grep: 'busca', Glob: 'busca', Read: 'ler', Edit: 'editar', Write: 'editar', Bash: 'terminal', PowerShell: 'terminal', Agent: 'agente', Task: 'agente', WebFetch: 'web', WebSearch: 'web' };
EF.poco = { nome: 'Block Well', insp: 'falling blocks', vira: 'the piece shaped like the tool type', D: 3.4, draw(g, t, tool) {
  g.clear(P.bg); const X = 58, C = 4, cols = 10, rows = 20;
  g.r(X - 2, 4, cols * C + 4, rows * C + 2, P.gray); g.r(X, 4, cols * C, rows * C, mix(P.bg, P.gray, .12));
  const f = FORMAS[FORMA_DE[tool] || 'ler']; const fh = Math.max(...f.map(p => p[0])) + 1; const c0 = 3;
  const baixo = f.filter(p => p[0] === fh - 1).map(p => p[1] + c0);
  const R = rng(10); const limpa = t > 1.9;
  for (let r = rows - 3; r < rows; r++) for (let c = 0; c < cols; c++) {
    const ultima = r === rows - 1; if (ultima && baixo.includes(c)) continue; if (!ultima && (R() < .45 || f.some(p => p[1] + c0 === c && rows - fh + p[0] === r))) continue;
    if (ultima && limpa) { if (t < 2.35) g.r(X + c * C, 4 + r * C, C - 1, C - 1, Math.floor(t * 10) % 2 ? P.white : P.a[c % 6]); continue; }
    g.r(X + c * C, 4 + (r + (ultima || !limpa || t < 2.35 ? 0 : 1)) * C, C - 1, C - 1, P.a[(c + r) % 6]);
  }
  const yb = Math.min(rows - fh, Math.floor(fase(t, 0, 1.9) * (rows - fh + 2)) - 2);
  if (!limpa || t < 2.35) f.forEach(([r, c]) => { const y = yb + r; if (y >= 0 && !(limpa && y === rows - 1)) g.r(X + (c + c0) * C, 4 + y * C, C - 1, C - 1, limpa && y === rows - 1 ? P.white : tc(tool)); });
  g.t('NEXT', 112, 6, P.ink, 7); g.t(tool, 112, 16, tc(tool), 7); g.t('LINES ' + (t > 2.35 ? 1 : 0), 112, 70, P.ink, 7);
} };
