        for (const r of S.rocks) { r.x = wx(r.x + r.vx * dt); r.y = wy(r.y + r.vy * dt); }
        if (!S.rocks.length) { S.onda++; novaOnda(); }
        for (const r of S.rocks) if (!r.tool && S.fila.length) r.tool = S.fila.shift();
        S.proxSau -= dt; if (!S.sau && (S.saus || S.proxSau <= 0)) { const d = Math.random() < .5 ? 1 : -1; S.sau = { x: d > 0 ? -6 : 166, y: R(24, 110), vx: d * 26, tool: S.saus ? 'Agent' : null, t: 0 }; if (S.saus) S.saus--; S.proxSau = R(14, 22); }
        if (S.sau) { const u = S.sau; u.x += u.vx * dt; u.t += dt; if (u.t > 1.2 && u.t < 99) { u.t = 0; const a = R(0, 6.28); S.sbul.push({ x: u.x, y: u.y, vx: Math.cos(a) * 40, vy: Math.sin(a) * 40, v: 1.6 }); } if (u.x < -10 || u.x > 170) S.sau = null; }
