        const alvo = (S.sau && S.sau.tool) ? S.sau : (S.rocks.find(r => r.tool) || S.rocks.reduce((m, r) => !m || dd(r, sh) < dd(m, sh) ? r : m, null));
        if (alvo) { const d = dd(alvo, sh), tf = d / 90; let ax = alvo.x + (alvo.vx || 0) * tf - sh.x, ay = alvo.y + (alvo.vy || 0) * tf - sh.y; if (Math.abs(ax) > LW / 2) ax -= Math.sign(ax) * LW; if (Math.abs(ay) > H / 2) ay -= Math.sign(ay) * H;
          const des = Math.atan2(ay, ax); let df = ((des - sh.a + Math.PI * 3) % (Math.PI * 2)) - Math.PI; sh.a += Math.max(-3.2 * dt, Math.min(3.2 * dt, df));
          if (Math.abs(df) < .1 && S.bul.length < 4 && S.cool <= 0 && sh.hip <= 0) { S.bul.push({ x: sh.x + Math.cos(sh.a) * 5, y: sh.y + Math.sin(sh.a) * 5, vx: Math.cos(sh.a) * 95, vy: Math.sin(sh.a) * 95, v: 1.5 }); S.cool = .22; } }
        sh.vx *= 1 - .5 * dt; sh.vy *= 1 - .5 * dt; sh.x = wx(sh.x + sh.vx * dt); sh.y = wy(sh.y + sh.vy * dt);
        for (const b of S.bul) { b.x = wx(b.x + b.vx * dt); b.y = wy(b.y + b.vy * dt); b.v -= dt; }
