        if (S.sau) { g.sp(['..xxxx..', 'xxxxxxxx', '.xxxxxx.'], S.sau.x - 4, S.sau.y - 1, 0x46); if (S.sau.tool) et.push([S.sau.tool, S.sau.x, S.sau.y - 9, corDe(S.sau.tool)]); }
        for (const b of S.sbul) g.r(b.x, b.y, 2, 2, 0x46); for (const b of S.bul) g.r(b.x, b.y, 2, 2, 0x0E);
        for (const e of S.ex) { const r = e.r * (e.t / .4); for (let n = 0; n < 8; n++) { const a = n * Math.PI / 4; g.r(e.x + Math.cos(a) * r, e.y + Math.sin(a) * r, 2, 2, (g.quadro >> 1) & 1 ? e.cor : 0x0E); } }
        const sh = S.ship; if (!(sh.hip > 0 && (g.quadro >> 1) & 1)) { const a = sh.a, p = (k, l) => [sh.x + Math.cos(a + k) * l, sh.y + Math.sin(a + k) * l], n = p(0, 5), l = p(2.5, 4), r = p(-2.5, 4);
          linha(g, n[0], n[1], l[0], l[1], 0x0E); linha(g, n[0], n[1], r[0], r[1], 0x0E); linha(g, l[0], l[1], r[0], r[1], 0x0E); }
