    const FASES = [{ ceu: 0x86, mont: 0xD2, chao: [0xC6, 0xC8], rua: [0x06, 0x08], bor: [0x46, 0x0E] }, { ceu: 0x3A, mont: 0x62, chao: [0xC2, 0xC4], rua: [0x04, 0x06], bor: [0x44, 0x0A] }, { ceu: 0x00, mont: 0x02, chao: [0x00, 0x00], rua: [0x02, 0x00], bor: [0x04, 0x02] }, { ceu: 0x4A, mont: 0x62, chao: [0xC2, 0xC4], rua: [0x04, 0x06], bor: [0x44, 0x0A] }];
