    jato: ['xx......', '.xx.....', 'xxxxxxx.', '.xxxxxxx', '.xx.....', 'xx......'],
    casa: ['..xxxx..', '.xxxxxx.', 'xxxxxxxx', 'xxxxxxxx', 'xxxxxxxx'],
    janela: ['........', '........', '........', '.x..x..x', '........'],
    arvore: ['..xxxx..', '.xxxxxx.', 'xxxxxxxx', 'xxxxxxxx', '.xxxxxx.', '..xxxx..', '...xx...', '...xx...'],
    estouro: [['x..x..x.', '.x...x..', '..x.x..x', 'xx...xx.', '..x.x...', '.x...x.x', 'x..x..x.'],
              ['.x..x..x', 'x..x.x..', '.x.....x', '..xx.xx.', 'x......x', '..x.x.x.', '.x..x..x']]
