  // depot letters, 4 dots wide, stacked
  const FUEL = [['xxxx', 'x...', 'xxx.', 'x...'], ['x..x', 'x..x', 'x..x', 'xxxx'], ['xxxx', 'xxx.', 'x...', 'xxxx'], ['x...', 'x...', 'x...', 'xxxx']];
  const DEP_H = 21, MEIA = { navio: 8, heli: 4, dep: 4, jato: 4 }, ALT = { navio: 5, heli: 6, dep: DEP_H, jato: 6 };

  function rng(seed) { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
