      ctx.strokeStyle = '#3d4038'; ctx.lineWidth = 2; ctx.setLineDash([6, 6]);
      ctx.strokeRect(X0, y - 6, XF - X0, 12); ctx.setLineDash([]);
      for (i = 0; i < 6; i++) chave(ctx, X0 + i * PASSO + 16, yc + 44, false);
