      ctx.fillStyle = '#ffd35a'; ctx.fillText(S.slots[0].a.model + (S.slots[0].a.effort ? ' · ' + S.slots[0].a.effort : ''), tx, l2);
      ctx.fillStyle = '#f2efe2'; ctx.textAlign = 'right'; ctx.fillText(sessA.length + (sessA.length === 1 ? ' action' : ' actions'), 234, l2); ctx.textAlign = 'left';
      ctx.fillText('CTX', tx, l3);
      R(ctx, '#2c2c2a', 62, l3 + 4, 124, 12);
      R(ctx, S.ctx > 80 ? '#ff5a4a' : '#f2efe2', 62, l3 + 4, 124 * S.ctx / 100, 12);
      for (i = 1; i < 10; i++) R(ctx, '#151515', 62 + i * 12.4, l3 + 4, 1, 12);
      ctx.fillStyle = '#f2efe2'; ctx.textAlign = 'right'; ctx.fillText(S.ctx + '%', 234, l3); ctx.textAlign = 'left';
      ctx.fillStyle = '#8fe08f'; ctx.fillText('US$ ' + S.usd, tx, l4);
