      ctx.fillStyle = '#ffd35a'; ctx.textAlign = 'right'; ctx.fillText('BYPASS', 234, l1); ctx.textAlign = 'left';
      lampada(ctx, tx + 5, l2 + 10, 4, '#63e06a', true);
