/* ================= IDEA 2 · TELETEXT ================= */
var K = '#000', R_ = '#f00', G_ = '#0f0', Y_ = '#ff0', B_ = '#00f', M_ = '#f0f', C_ = '#0ff', W_ = '#fff';
