  if (fd) P.bg(c + 2, r, 3, fd, 2);
  P.icone(c + 2, r, a.tool, cr, clamp((k - 0.14) / 0.5));
  // lamp: blinking yellow = running, green = ok, red = error
  if (k > 0.5) { var lc = run ? (pisca ? Y_ : K) : err ? R_ : G_; P.mos(c + 5, r, 16 | 32, lc); P.mos(c + 5, r + 1, 1 | 2, lc); }
