    q('a'); ctx.fillRect(x + 2, y, w - 4, th);
    q('g'); ctx.fillRect(x + 2, y + h / 2 - 2, w - 4, th);
    q('d'); ctx.fillRect(x + 2, y + h - th, w - 4, th);
    q('f'); ctx.fillRect(x, y + 2, th, h / 2 - 3);
