    Object.assign(d.style, { left: r.x + '%', top: r.y + '%', width: r.w + '%', height: r.h + '%' });
    const rt = document.createElement('div'); rt.className = 'rt'; rt.textContent = r.nome;
    const sm = document.createElement('small'); sm.textContent = T.forma === 'lotus' ? r.faixa : r.sub; rt.appendChild(sm);
    const rc = document.createElement('div'); rc.className = 'rc';
